FBF-Kolkata\' when fulfilment_source = \'gur_san_wh_nl_01nl\' then \'FBF-Gurgoan\' else fulfilment_source end as Facility ,sum(cast(quantity as int64)) Units_sold ,sum(cast(line_item_sales as Float64)) as Selling_price from maplemonk.hyuman_flipkart_fact_items where UPPER(order_item_status) NOT IN(\'RETURNED\',\'CANCELLED\',\'RETURN REQUESTED\',\'UNDELIVERED\') and fulfilment_type = \'FBF\' group by 1,2,3,4,5,6,7 union all select \'Blinkit\' as source ,Date(order_date) Order_date ,commonsku as sku ,\'Blinkit\' as Marketplace ,product_name ,category ,\'Blinkit\' as Facility ,sum(cast(quantity as int64)) as Units_sold ,sum(cast(Selling_price as Float64)) Selling_Price from MapleMonk.Hyuman_Blinkit_Fact_items group by 1,2,3,4,5,6,7; Create or replace table Maplemonk.Hyuman_DRR_Sales_Consolidate as SELECT source, sku, marketplace, product_name_final, product_category, facility, SUM( CASE WHEN DATE(order_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 7 DAY) THEN IFNULL(units_sold,0) ELSE 0 END) AS sold_qty_7d, SUM( CASE WHEN DATE(order_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 7 DAY) THEN IFNULL(selling_price,0) ELSE 0 END) AS sales_value_7d, SUM( CASE WHEN DATE(order_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 14 DAY) THEN IFNULL(units_sold,0) ELSE 0 END ) AS sold_qty_14d, SUM( CASE WHEN DATE(order_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 14 DAY) THEN IFNULL(selling_price,0) ELSE 0 END) AS sales_value_14d, SUM( CASE WHEN DATE(order_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 28 DAY) THEN IFNULL(units_sold,0) ELSE 0 END ) AS sold_qty_28d, SUM( CASE WHEN DATE(order_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 28 DAY) THEN IFNULL(selling_price,0) ELSE 0 END ) AS sales_value_28d, SUM( CASE WHEN DATE(order_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 56 DAY) THEN IFNULL(units_sold,0) ELSE 0 END) AS sold_qty_56d, SUM( CASE WHEN DATE(order_date) >= DATE_SUB(CURRENT_DATE(), INTERVAL 56 DAY) THEN IFNULL(selling_price,0) ELSE 0 END) AS sales_value_56d FROM Maplemonk.Hyuman_DRR_Sales_Consolidated_Intermediate GROUP BY 1,2,3,4,5,6;",
